import { currentDomainID, getCurrentDomainID } from "../domain-id/index.js";
import { tryCatch } from "../tool.js";
import { bytecloudAsyncJwtService } from "./async-jwt.service.js";
import { JwtStorageKey } from "./jwt.constant.js";
import { parseJwt } from "@bytecloud/core-lib";
const jwt_util_parseJwt = (token)=>parseJwt(token);
