const getSessionStorageKey = (name)=>`__cloud_init_config-${name}__`;
const initConfig = (config)=>{
    try {
        Object.keys(null != config ? config : {}).forEach((key)=>{
            if ('string' == typeof config[key]) window.sessionStorage.setItem(getSessionStorageKey(key), config[key]);
        });
    } catch (error) {
        console.error(error);
    }
};
export { getSessionStorageKey, initConfig };
